import * as THREE from 'three/webgpu';

export default function createNode(config, ctx) {
  // Destructure scene placement
  const { position, rotation, scale } = config.scenePlacement;

  // Load the brushed metal texture (cached loader)
  const texture = ctx.textureLoader.load(config.assets.imageUrl);

  // Create plane geometry (1x1 unit; scale will be applied via transform)
  const geometry = new THREE.PlaneGeometry(1, 1);

  // Static material: MeshBasicNodeMaterial (no lighting)
  const material = new THREE.MeshBasicNodeMaterial({
    map: texture,
  });

  // Build the mesh
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(position[0], position[1], position[2]);
  mesh.rotation.set(rotation[0], rotation[1], rotation[2]);
  mesh.scale.set(scale[0], scale[1], scale[2]);

  // No event handlers (non-interactive)
  mesh.userData.handlers = {};

  // Cleanup: dispose GPU resources and kill any GSAP timelines (none here)
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  return mesh;
}
